SELECT DISTINCT TOP 2500 EfProjekte.ID AS ID, EfProjekte.AuftragsNr AS AuftragsNr, EfProjekte.Stichwort AS Stichwort, EfProjekte.ID_Installateur AS ID_Installateur, EfProjekte.ID_Kontrolleur AS ID_Kontrolleur, EfProjekte.WerkNr AS WerkNr, EfProjekte.Jahr AS Jahr, EfProjekte.DatumInbetrieb AS DatumInbetrieb, EfProjekte.ID_Gebaeude AS ID_Gebaeude, EfProjekte.Gemeinde AS Gemeinde, EfProjekte.Strasse AS Strasse, EfProjekte.HausNr AS HausNr, EfProjekte.PLZ AS PLZ, EfProjekte.PostOrt AS PostOrt, EfProjekte.GebaeudeArt1 AS GebaeudeArt1, EfProjekte.GebaeudeArt2 AS GebaeudeArt2, EfProjekte.ParzelleNr AS ParzelleNr, EfProjekte.AssekuranzNr AS AssekuranzNr, EfProjekte.ID_Inhaber AS ID_Inhaber, EfProjekte.ID_Verwaltung AS ID_Verwaltung, EfProjekte.ExportStatus AS ExportStatus, EfProjekte.ID_Werk AS ID_Werk FROM (SELECT DISTINCT A.ID AS ID, A.AuftragsNr AS AuftragsNr, A.Stichwort AS Stichwort, A.GUID AS GUID, A.ExportStatus AS ExportStatus, A.ID_Installateur AS ID_Installateur, A.ID_Kontrolleur AS ID_Kontrolleur, A.ID_Werk AS ID_Werk, A.WerkNr AS WerkNr, A.Jahr AS Jahr, A.DatumInbetrieb AS DatumInbetrieb, G.ID AS ID_Gebaeude, G.Strasse AS Strasse, G.HausNr AS HausNr, G.HausNrSort AS HausNrSort, G.PLZ AS PLZ, G.PostOrt AS PostOrt, G.GebaeudeArt1 AS GebaeudeArt1, G.GebaeudeArt2 AS GebaeudeArt2, G.Gemeinde AS Gemeinde, G.ParzelleNr AS ParzelleNr, G.AssekuranzNr AS AssekuranzNr, G.ID_Inhaber AS ID_Inhaber, G.ID_Verwaltung AS ID_Verwaltung, A.ImportCRC FROM EAuftraege A JOIN ELeistungen L ON L.ID_Auftrag = A.ID JOIN EAnlagen Anl ON Anl.ID = L.ID_Objekt JOIN Gebaeude G ON G.ID = Anl.ID_Gebaeude LEFT OUTER JOIN GeschPartner Werk ON Werk.ID = A.ID_Werk) AS EfProjekte LEFT OUTER JOIN Adressen Inh ON Inh.ID = ID_Inhaber LEFT OUTER JOIN Adressen Verw ON Verw.ID = ID_Verwaltung WHERE (((UPPER(EfProjekte.Stichwort) LIKE UPPER("%biel%") OR UPPER(EfProjekte.Strasse) LIKE UPPER("%biel%") OR UPPER(EfProjekte.HausNr) = UPPER("biel") OR UPPER(EfProjekte.PLZ) LIKE UPPER("%biel%") OR UPPER(EfProjekte.PostOrt) LIKE UPPER("%biel%") OR UPPER(EfProjekte.Gemeinde) LIKE UPPER("%biel%") OR UPPER(Inh.Stichwort) LIKE UPPER("%biel%") OR UPPER(Verw.Stichwort) LIKE UPPER("%biel%"))) OR EfProjekte.ID IN (SELECT DISTINCT ID_Auftrag FROM (SELECT L.ID AS ID, L.ID_Auftrag AS ID_Auftrag, Anl.ID AS Anl_ID, Anl.ID_Gebaeude AS ID_Gebaeude, Anl.GebaeudeTeil AS GebaeudeTeil, Anl.Bezeichnung AS Bezeichnung, Anl.ZaehlerNr1 AS ZaehlerNr1, Anl.ZaehlerNr2 AS ZaehlerNr2, L.Erledigt AS Erledigt, L.LeistungsNr AS LeistungsNr, L.ID_Installateur AS ID_Installateur, L.ID_Kontrolleur AS ID_Kontrolleur, L.ID_SachbTechn AS ID_SachbTechn, L.WerkNr AS WerkNr, L.Jahr AS Jahr, Anl.ID_Inhaber AS ID_Inhaber, Anl.ID_Stromkunde AS ID_Stromkunde FROM ELeistungen L JOIN EAnlagen Anl ON Anl.ID = L.ID_Objekt) AS EfAnlagen JOIN Gebaeude G ON EfAnlagen.ID_Gebaeude = G.ID LEFT OUTER JOIN Adressen Inh ON Inh.ID = EfAnlagen.ID_Inhaber LEFT OUTER JOIN Adressen Stromk ON Stromk.ID = EfAnlagen.ID_Stromkunde LEFT OUTER JOIN Adressen GebInh ON GebInh.ID = G.ID_Inhaber JOIN EAuftraege Auf ON Auf.ID = EfAnlagen.ID_Auftrag WHERE ((UPPER(Inh.Stichwort) LIKE UPPER("%biel%") OR UPPER(Stromk.Stichwort) LIKE UPPER("%biel%") OR UPPER(GebInh.Stichwort) LIKE UPPER("%biel%"))))) ORDER BY EfProjekte.ID DESC
